  Test("A previously confirmed low load also recovers without another five-second wait",()=>{var raw=Enumerable.Range(0,7).Select(i=>new ChartSample(i*1000,[.5])).Concat([new ChartSample(7000,[.05]),new ChartSample(8000,[0]),new ChartSample(9000,[.5])]).ToArray();Eq(CurveSignalFilter.Apply("A2687",raw).All(p=>p.PlotVisible![0]),true);});
  Test("Unconfirmed cable pulses cannot acquire handshake grace or cross ports",()=>{ChartSample[] raw=[new(0,[.5,8]),new(1000,[.1,0]),new(2000,[0,0]),new(3000,[.5,8])];var f=CurveSignalFilter.Apply("A2687",raw);Eq(f.All(p=>!p.PlotVisible![0]),true);Eq(f.All(p=>p.PlotVisible![1]),true);});
  Test("Only confirmed per-port output starts public history, not summed idle or short pulses",()=>{var h=new PowerHistory();var t=DateTimeOffset.UtcNow;var s=DeviceState.Empty("A2687","no-record");s.Connected=true;foreach(var p in s.Ports)p.Power=.2;s.Updated=t;h.Record(s);Eq(h.Read(s).Length,0);s.Ports[0].Power=.5;s.Updated=t.AddSeconds(1);h.Record(s);s.Ports[0].Power=.6;s.Updated=t.AddSeconds(2);h.Record(s);Eq(h.Read(s).Length,0);foreach(var p in s.Ports)p.Power=0;s.Updated=t.AddSeconds(3);h.Record(s);Eq(h.Read(s).Length,0);s.Ports[0].Power=3;s.Updated=t.AddSeconds(4);h.Record(s);Eq(h.Read(s).Any(p=>p.PlotValues![0]==3),true);Eq(h.Read(s,t.AddMinutes(5).AddSeconds(5)).Length,0);});
  Test("Both chart windows use the same five-minute ceiling and integer padding",()=>{Eq(PowerCurve.Ceiling([100,1]),115.0);Eq(PowerCurve.Ceiling([.5]),2.0);Eq(PowerCurve.Ceiling([]),2.0);});
  Test("Confirmed low-power history remains visible as its confirmation start ages out",()=>{var h=new PowerHistory();var t=DateTimeOffset.UtcNow;var s=DeviceState.Empty("A2687","confirmed-tail");s.Connected=true;s.Ports[0].Power=.5;for(int i=0;i<7;i++){s.Updated=t.AddSeconds(i);h.Record(s,t.AddSeconds(i));}s.Ports[0].Power=0;s.Updated=t.AddSeconds(7);h.Record(s,t.AddSeconds(7));var tail=h.Read(s,t.AddMinutes(5).AddSeconds(3));Eq(tail.Count(p=>p.PlotValues![0]>.2),4);Eq(tail[0].At,t.AddSeconds(3).ToUnixTimeMilliseconds());});
