  Test("160W isolated 0.5/0.6W pulses are hidden without changing raw readings",()=>{ChartSample[] raw=[new(0,[.5]),new(1000,[.6]),new(2000,[0])];var filtered=CurveSignalFilter.Apply("A2687",raw);Eq(filtered.All(s=>s.PlotValues![0]==0),true);Eq(raw[0].Values[0],.5);Eq(filtered[1].Values[0],.6);});
  Test("160W sustained low load requires more than five seconds and backfills its start",()=>{ChartSample[] raw=Enumerable.Range(0,7).Select(i=>new ChartSample(i*1000,[.5])).ToArray();Eq(CurveSignalFilter.Apply("A2687",raw[..6]).All(s=>s.PlotValues![0]==0),true);Eq(CurveSignalFilter.Apply("A2687",raw).All(s=>s.PlotValues![0]==.5),true);});
