  Test("Low pulses after a real load do not inherit confirmation or erase the old curve",()=>{ChartSample[] raw=[new(0,[8]),new(1000,[.5]),new(2000,[.6]),new(3000,[0])];var f=CurveSignalFilter.Apply("A2687",raw);Eq(f[0].PlotValues![0],8.0);Eq(f.Skip(1).All(s=>s.PlotValues![0]==0),true);});
